def rule_us_district_court_origin(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_span(text: str, source_item: dict) -> None:
            cleaned = re.sub(r"\s+", " ", (text or "")).strip().rstrip(".,;:")
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 120)
            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                upper = text.upper()
                if any(upper.startswith(stop) for stop in _STOP_LABELS):
                    break

                label_pos = text.find(_APPEAL_LABEL)
                if label_pos < 0:
                    continue

                remainder = text[label_pos + len(_APPEAL_LABEL):].strip()
                if remainder:
                    # Some OCR variants keep the district line on the same row.
                    if remainder.lower().startswith("for the "):
                        add_span(remainder, item)
                        continue

                for j in range(i + 1, min(limit, i + 6)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue

                    next_upper = next_text.upper()
                    if any(next_upper.startswith(stop) for stop in _STOP_LABELS):
                        break

                    if next_text.lower().startswith("for the "):
                        add_span(next_text, next_item)
                        break

                    # A few pages may omit the literal "for the" prefix.
                    if (
                        "judge" not in next_text.lower()
                        and re.search(r"(?i)\b(?:district|circuit)\b", next_text)
                    ):
                        add_span(next_text, next_item)
                        break

        def scan_history_items(items: list[dict]) -> None:
            for i, item in enumerate(items or []):
                text = (item or {}).get("text") or ""
                lower = text.lower()
                if "appeal" not in lower or "united states district court for the" not in lower:
                    continue

                tail = text.split("United States District Court for the", 1)[1].strip()
                if tail:
                    add_span(tail.split(",")[0].strip(), item)
                else:
                    for j in range(i + 1, min(len(items or []), i + 4)):
                        next_item = items[j] or {}
                        next_text = (next_item.get("text") or "").strip()
                        if not next_text:
                            continue
                        if "judge" in next_text.lower():
                            continue
                        if re.search(r"(?i)\bdistrict\b", next_text):
                            add_span(next_text.split(",")[0].strip(), next_item)
                            break

                for j in range(i + 1, min(len(items or []), i + 60)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue
                    if "judge" in next_text.lower():
                        continue
                    if "united states district court for the" not in next_text.lower():
                        continue
                    district_tail = next_text.split("United States District Court for the", 1)[1].strip()
                    if district_tail:
                        add_span(district_tail.split(",")[0].strip(), next_item)

        scan_items(doc.get("lines") or [])
        scan_items(doc.get("paragraphs") or [])
        scan_history_items(doc.get("lines") or [])
        scan_history_items(doc.get("paragraphs") or [])

        if not spans:
            full_text = doc.get("text") or ""
            for match in re.finditer(re.escape(_APPEAL_LABEL), full_text):
                start = match.end()
                tail = full_text[start:start + 180]
                tail = tail.lstrip(" \t\r\n")
                line = tail.splitlines()[0].strip() if tail else ""
                if line.lower().startswith("for the "):
                    add_span(line, {})

        return spans
    except Exception:
        return []

def rule_court_of_appeals_docket_numbers(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        spans = []
        seen = set()

        docket_re = re.compile(r"\b\d{1,2}(?:A)?-\d{1,6}(?:-\d{1,6})?\b")
        label_only_re = re.compile(r"(?i)^Nos?\.?$")
        label_anywhere_re = re.compile(r"(?i)\bNos?\.?")

        def add_matches(text: str, line: dict) -> None:
            for match in docket_re.finditer(text):
                value = match.group(0).rstrip(".,;:")
                key = (line.get("page_no"), line.get("line_no"), value)
                if key in seen:
                    continue
                seen.add(key)
                span = {"text": value}
                if "page_no" in line:
                    span["page_no"] = line["page_no"]
                if "line_no" in line:
                    span["line_no"] = line["line_no"]
                spans.append(span)

        limit = min(len(lines), 60)

        for i in range(limit):
            line = lines[i] or {}
            text = (line.get("text") or "").strip()
            if not text:
                continue
            if text.upper().startswith("D.C."):
                continue

            if label_anywhere_re.search(text):
                if docket_re.search(text):
                    add_matches(text, line)
                    if text.rstrip().endswith(",") or text.rstrip().endswith(";"):
                        for j in range(i + 1, min(limit, i + 6)):
                            next_line = lines[j] or {}
                            next_text = (next_line.get("text") or "").strip()
                            if not next_text:
                                continue
                            if next_text.upper().startswith("D.C."):
                                continue
                            if docket_re.search(next_text):
                                add_matches(next_text, next_line)
                    continue

                if label_only_re.fullmatch(text):
                    for j in range(i + 1, min(limit, i + 6)):
                        next_line = lines[j] or {}
                        next_text = (next_line.get("text") or "").strip()
                        if not next_text:
                            continue
                        if next_text.upper().startswith("D.C."):
                            continue
                        if docket_re.search(next_text):
                            add_matches(next_text, next_line)

        return spans
    except Exception:
        return []

import re


_COLON_RE = re.compile(
    r"^\s*CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)\s*$",
    re.IGNORECASE,
)
_STANDARD_RE = re.compile(
    r"^\s*CPF\s+([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\s*$",
    re.IGNORECASE,
)
_TEXT_RE = re.compile(
    r"(?:^|\n)\s*CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)\s*(?:$|\n)|"
    r"(?:^|\n)\s*(CPF\s+[1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\s*(?:$|\n)",
    re.IGNORECASE,
)
_ANYWHERE_RE = re.compile(
    r"CPF\s*:\s*([1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*-\s*NOPV)|"
    r"\b(CPF\s+[1-5]\s*-\s*\d{4}\s*-\s*\d{3}\s*(?:-\s*|\s+)NOPV)\b",
    re.IGNORECASE,
)


def rule_cpf_case_number(doc: dict) -> list[dict]:
    try:
        for source_key in ("lines", "paragraphs"):
            for item in doc.get(source_key) or []:
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                colon_match = _COLON_RE.match(text)
                if colon_match:
                    span = {"text": colon_match.group(1).strip()}
                    if "page_no" in item:
                        span["page_no"] = item["page_no"]
                    if "line_no" in item:
                        span["line_no"] = item["line_no"]
                    if "paragraph_no" in item:
                        span["paragraph_no"] = item["paragraph_no"]
                    return [span]

                standard_match = _STANDARD_RE.match(text)
                if standard_match:
                    span = {
                        "text": f"The CPF case number assigned to this enforcement action is {text}"
                    }
                    if "page_no" in item:
                        span["page_no"] = item["page_no"]
                    if "line_no" in item:
                        span["line_no"] = item["line_no"]
                    if "paragraph_no" in item:
                        span["paragraph_no"] = item["paragraph_no"]
                    return [span]

        full_text = (doc.get("text") or "").strip()
        if full_text:
            text_match = _TEXT_RE.search(full_text)
            if text_match:
                text = text_match.group(1) or text_match.group(2)
                if text:
                    if text_match.group(1):
                        return [{"text": text.strip()}]
                    return [
                        {
                            "text": f"The CPF case number assigned to this enforcement action is {text.strip()}",
                        }
                    ]

            anywhere_match = _ANYWHERE_RE.search(full_text)
            if anywhere_match:
                text = anywhere_match.group(1) or anywhere_match.group(2)
                if text:
                    if anywhere_match.group(1):
                        return [{"text": text.strip()}]
                    return [
                        {
                            "text": f"The CPF case number assigned to this enforcement action is {text.strip()}",
                        }
                    ]

        return []
    except Exception:
        return []

